//! Wisp invite codes.
//!
//! An invite code is the only way to create an account. Codes are single-use,
//! expiring, and generated by the owner through the admin CLI.
//!
//! # Shape
//!
//! ```text
//! WISP-A1B2-C3D4-E5F6-G7H8
//! ```
//!
//! Sixteen characters of [Crockford base32][crockford] in four groups: thirteen
//! carry 64 bits of secret, three are a checksum. The `WISP-` prefix is a
//! human affordance — it makes a code recognisable when pasted into a chat or
//! written on paper — and is optional on input.
//!
//! [crockford]: https://www.crockford.com/base32.html
//!
//! # Why Crockford base32
//!
//! People retype these from a message or a sticky note. Crockford's alphabet
//! omits `I`, `L`, `O`, and `U`, and treats `I`/`L` as `1` and `O` as `0` on
//! input, so the classic transcription mistakes decode to the right value
//! instead of failing. (`U` is omitted so that a random code cannot spell
//! something unfortunate.) Case is ignored.
//!
//! # Why there is a checksum
//!
//! A mistyped code is caught locally, before it reaches the network. That
//! matters because redemption attempts are rate-limited server-side: without a
//! local check, a user fumbling a character would burn attempts against their
//! own invite and could lock themselves out of onboarding.
//!
//! # What the server stores
//!
//! **Never the code itself — only [`InviteCode::redemption_hash`].** A code is
//! a bearer credential, exactly like a password: anyone holding it can create
//! an account. Storing hashes means a leaked database contains no usable
//! invites. The admin CLI shows the code once, at generation, and cannot
//! recover it afterwards.
//!
//! A plain SHA-256 is the right choice here, unlike for a passphrase: the input
//! is 64 bits of uniform randomness from the OS CSPRNG, not something a person
//! chose, so there is no dictionary to attack and nothing for a slow KDF to buy.

use std::fmt;

use rand_core::{OsRng, RngCore};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

/// Crockford base32. No `I`, `L`, `O`, or `U`.
const ALPHABET: &[u8; 32] = b"0123456789ABCDEFGHJKMNPQRSTVWXYZ";

const SECRET_BYTES: usize = 8;
/// ceil(64 bits / 5 bits per character).
const SECRET_CHARS: usize = 13;
const CHECK_CHARS: usize = 3;
const TOTAL_CHARS: usize = SECRET_CHARS + CHECK_CHARS;

const PREFIX: &str = "WISP";
const GROUP: usize = 4;

const HASH_DOMAIN: &[u8] = b"wisp.invite.v1.redemption";
const CHECK_DOMAIN: &[u8] = b"wisp.invite.v1.checksum";

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum InviteError {
    #[error("invite code must be {TOTAL_CHARS} characters (got {got})")]
    WrongLength { got: usize },

    #[error("invite code contains a character that is not valid: {0:?}")]
    BadCharacter(char),

    #[error("invite code looks mistyped")]
    BadChecksum,
}

/// A single-use invite code.
///
/// Comparison is constant-time, so a code cannot be recovered character by
/// character from timing.
#[derive(Clone)]
pub struct InviteCode {
    secret: [u8; SECRET_BYTES],
}

impl InviteCode {
    /// Generates a fresh code from the OS CSPRNG.
    pub fn generate() -> Self {
        let mut secret = [0u8; SECRET_BYTES];
        OsRng.fill_bytes(&mut secret);
        Self { secret }
    }

    /// Parses a code, tolerating the optional prefix, any grouping, case, and
    /// the Crockford ambiguous-character aliases.
    pub fn parse(input: &str) -> Result<Self, InviteError> {
        let mut chars = Vec::with_capacity(TOTAL_CHARS);

        // Strip the prefix if present, then keep only alphanumerics so that
        // hyphens, spaces, and stray punctuation from a copy-paste all vanish.
        let body = input.trim();
        let body = body
            .strip_prefix(PREFIX)
            .or_else(|| body.strip_prefix(&PREFIX.to_lowercase()))
            .unwrap_or(body);

        for c in body.chars() {
            if c.is_ascii_alphanumeric() {
                chars.push(normalise_char(c)?);
            } else if c == '-' || c == ' ' || c == '_' {
                continue;
            } else {
                return Err(InviteError::BadCharacter(c));
            }
        }

        if chars.len() != TOTAL_CHARS {
            return Err(InviteError::WrongLength { got: chars.len() });
        }

        // The 13-character secret field holds 65 bits but the secret is only
        // 64, so the leading character carries one padding bit that encoding
        // always leaves clear. Rejecting a set padding bit keeps the encoding
        // injective: without this, the two characters that differ only in that
        // bit decode to the same secret, so one code would have two spellings
        // and a typo in that position would silently succeed.
        if chars[0] >= 16 {
            return Err(InviteError::BadChecksum);
        }

        let secret = decode_secret(&chars[..SECRET_CHARS]);
        let expected = checksum_values(&secret);
        // Constant-time: the checksum is derived from the secret, so a
        // variable-time comparison would leak information about it.
        if !bool::from(chars[SECRET_CHARS..].ct_eq(&expected)) {
            return Err(InviteError::BadChecksum);
        }

        Ok(Self { secret })
    }

    /// What the server stores and compares against. Never store the code.
    pub fn redemption_hash(&self) -> RedemptionHash {
        let mut hasher = Sha256::new();
        hasher.update(HASH_DOMAIN);
        hasher.update(self.secret);
        RedemptionHash(hasher.finalize().into())
    }
}

impl fmt::Display for InviteCode {
    /// Renders the canonical, grouped form: `WISP-A1B2-C3D4-E5F6-G7H8`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut chars = encode_secret(&self.secret);
        chars.extend_from_slice(&checksum_chars(&self.secret));

        f.write_str(PREFIX)?;
        for group in chars.chunks(GROUP) {
            write!(f, "-{}", String::from_utf8_lossy(group))?;
        }
        Ok(())
    }
}

/// Deliberately does not print the code — a `Debug` log must not leak a live
/// bearer credential.
impl fmt::Debug for InviteCode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "InviteCode(redacted)")
    }
}

impl PartialEq for InviteCode {
    fn eq(&self, other: &Self) -> bool {
        self.secret.ct_eq(&other.secret).into()
    }
}

impl Eq for InviteCode {}

/// SHA-256 of an invite code, as stored server-side.
#[derive(Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct RedemptionHash(#[serde(with = "hex_array")] pub [u8; 32]);

impl RedemptionHash {
    pub fn to_hex(self) -> String {
        self.0.iter().map(|b| format!("{b:02x}")).collect()
    }

    pub fn from_hex(text: &str) -> Option<Self> {
        if text.len() != 64 {
            return None;
        }
        let mut out = [0u8; 32];
        for (i, byte) in out.iter_mut().enumerate() {
            *byte = u8::from_str_radix(text.get(i * 2..i * 2 + 2)?, 16).ok()?;
        }
        Some(Self(out))
    }

    /// Constant-time comparison, for the server's redemption lookup.
    pub fn matches(&self, other: &Self) -> bool {
        self.0.ct_eq(&other.0).into()
    }
}

impl fmt::Debug for RedemptionHash {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "RedemptionHash({})", self.to_hex())
    }
}

mod hex_array {
    use serde::{Deserialize, Deserializer, Serializer};

    pub fn serialize<S: Serializer>(bytes: &[u8; 32], s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&bytes.iter().map(|b| format!("{b:02x}")).collect::<String>())
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<[u8; 32], D::Error> {
        let text = String::deserialize(d)?;
        super::RedemptionHash::from_hex(&text)
            .map(|h| h.0)
            .ok_or_else(|| serde::de::Error::custom("expected 64 hex characters"))
    }
}

/// Maps a character to its base32 value, applying the Crockford aliases.
fn normalise_char(c: char) -> Result<u8, InviteError> {
    let upper = c.to_ascii_uppercase();
    let upper = match upper {
        // The transcription mistakes Crockford's alphabet is designed around.
        'I' | 'L' => '1',
        'O' => '0',
        other => other,
    };
    ALPHABET
        .iter()
        .position(|&a| a == upper as u8)
        .map(|v| v as u8)
        .ok_or(InviteError::BadCharacter(c))
}

/// Packs 8 bytes into 13 base32 characters, big-endian, zero-padded.
fn encode_secret(secret: &[u8; SECRET_BYTES]) -> Vec<u8> {
    let value = u64::from_be_bytes(*secret);
    let mut out = vec![0u8; SECRET_CHARS];
    // 13 characters hold 65 bits; the value occupies the low 64, so the top
    // character carries a single padding bit that is always zero.
    for (i, slot) in out.iter_mut().enumerate() {
        let shift = 5 * (SECRET_CHARS - 1 - i);
        let index = if shift >= 64 {
            0
        } else {
            ((value >> shift) & 0x1F) as usize
        };
        *slot = ALPHABET[index];
    }
    out
}

/// Inverse of [`encode_secret`]. Values are already validated by the caller.
fn decode_secret(values: &[u8]) -> [u8; SECRET_BYTES] {
    let mut acc: u64 = 0;
    for &v in values {
        acc = acc.wrapping_shl(5) | u64::from(v);
    }
    acc.to_be_bytes()
}

/// Three base32 *values* derived from the secret, purely for typo detection.
///
/// Values, not characters: parsing works in the value domain, and having the
/// two representations meet in one place stops them being compared against
/// each other by mistake.
fn checksum_values(secret: &[u8; SECRET_BYTES]) -> [u8; CHECK_CHARS] {
    let mut hasher = Sha256::new();
    hasher.update(CHECK_DOMAIN);
    hasher.update(secret);
    let digest = hasher.finalize();

    let mut out = [0u8; CHECK_CHARS];
    for (i, slot) in out.iter_mut().enumerate() {
        *slot = digest[i] % 32;
    }
    out
}

/// The checksum rendered as base32 characters, for display.
fn checksum_chars(secret: &[u8; SECRET_BYTES]) -> [u8; CHECK_CHARS] {
    let mut out = checksum_values(secret);
    for slot in out.iter_mut() {
        *slot = ALPHABET[*slot as usize];
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_codes_round_trip() {
        for _ in 0..500 {
            let code = InviteCode::generate();
            let rendered = code.to_string();
            assert_eq!(InviteCode::parse(&rendered).unwrap(), code);
        }
    }

    #[test]
    fn canonical_form_is_grouped_and_prefixed() {
        let rendered = InviteCode::generate().to_string();
        assert!(rendered.starts_with("WISP-"), "{rendered}");
        // WISP + 4 groups of 4, each preceded by a hyphen.
        assert_eq!(rendered.len(), PREFIX.len() + 4 * (GROUP + 1));
        for group in rendered.split('-').skip(1) {
            assert_eq!(group.len(), GROUP);
        }
    }

    #[test]
    fn generated_codes_are_distinct() {
        let a = InviteCode::generate();
        let b = InviteCode::generate();
        assert_ne!(a, b);
        assert_ne!(a.redemption_hash(), b.redemption_hash());
    }

    #[test]
    fn parsing_ignores_case_grouping_and_prefix() {
        let code = InviteCode::generate();
        let canonical = code.to_string();
        let bare = canonical.trim_start_matches("WISP-").replace('-', "");

        for variant in [
            canonical.clone(),
            canonical.to_lowercase(),
            bare.clone(),
            bare.to_lowercase(),
            format!("  {canonical}  "),
            bare.chars()
                .collect::<Vec<_>>()
                .chunks(2)
                .map(|c| c.iter().collect::<String>())
                .collect::<Vec<_>>()
                .join(" "),
        ] {
            assert_eq!(
                InviteCode::parse(&variant).unwrap(),
                code,
                "failed to parse {variant:?}"
            );
        }
    }

    /// The whole point of the Crockford alphabet: these are the characters
    /// people get wrong when retyping, and they must decode correctly.
    #[test]
    fn crockford_aliases_decode_to_the_intended_character() {
        assert_eq!(normalise_char('I').unwrap(), normalise_char('1').unwrap());
        assert_eq!(normalise_char('l').unwrap(), normalise_char('1').unwrap());
        assert_eq!(normalise_char('O').unwrap(), normalise_char('0').unwrap());
        assert_eq!(normalise_char('o').unwrap(), normalise_char('0').unwrap());
    }

    #[test]
    fn ambiguous_characters_are_absent_from_the_alphabet() {
        for excluded in [b'I', b'L', b'O', b'U'] {
            assert!(
                !ALPHABET.contains(&excluded),
                "{} must not be in the alphabet",
                excluded as char
            );
        }
        assert_eq!(ALPHABET.len(), 32);
    }

    #[test]
    fn a_single_wrong_character_is_caught_locally() {
        let code = InviteCode::generate();
        let canonical = code.to_string();
        let bare: Vec<char> = canonical.trim_start_matches("WISP-").replace('-', "").chars().collect();

        let mut caught = 0;
        for position in 0..bare.len() {
            for &replacement in ALPHABET.iter() {
                if replacement as char == bare[position] {
                    continue;
                }
                let mut typo = bare.clone();
                typo[position] = replacement as char;
                let typo: String = typo.into_iter().collect();

                match InviteCode::parse(&typo) {
                    Err(InviteError::BadChecksum) => caught += 1,
                    // A different valid code is astronomically unlikely but not
                    // impossible with a 15-bit checksum; it must at least never
                    // decode back to *this* code.
                    Ok(other) => assert_ne!(other, code),
                    Err(e) => panic!("unexpected error for {typo:?}: {e}"),
                }
            }
        }
        // 15 bits of checksum: essentially every single-character typo is
        // caught. Allow a tiny margin rather than asserting perfection.
        let total = bare.len() * 31;
        assert!(
            caught as f64 / total as f64 > 0.99,
            "only caught {caught}/{total} single-character typos"
        );
    }

    /// Every code must have exactly one spelling.
    #[test]
    fn encoding_is_injective() {
        let code = InviteCode::generate();
        let bare: Vec<char> = code
            .to_string()
            .trim_start_matches("WISP-")
            .replace('-', "")
            .chars()
            .collect();

        // The leading character encodes only 4 meaningful bits, so the value
        // 16 higher differs solely in the padding bit.
        let leading = normalise_char(bare[0]).unwrap();
        assert!(leading < 16, "encoding must leave the padding bit clear");

        let mut alias = bare.clone();
        alias[0] = ALPHABET[(leading + 16) as usize] as char;
        let alias: String = alias.into_iter().collect();

        assert!(
            InviteCode::parse(&alias).is_err(),
            "{alias:?} is a second spelling of the same code"
        );
    }

    #[test]
    fn wrong_length_is_rejected() {
        assert!(matches!(
            InviteCode::parse("WISP-A1B2-C3D4"),
            Err(InviteError::WrongLength { .. })
        ));
        assert!(matches!(
            InviteCode::parse(""),
            Err(InviteError::WrongLength { got: 0 })
        ));
    }

    #[test]
    fn invalid_characters_are_rejected() {
        // 'U' is not in the alphabet and has no alias.
        assert!(matches!(
            InviteCode::parse("UUUUUUUUUUUUUUUU"),
            Err(InviteError::BadCharacter('U'))
        ));
        assert!(matches!(
            InviteCode::parse("WISP-A1B2-C3D4-E5F6-G7H!"),
            Err(InviteError::BadCharacter('!'))
        ));
    }

    #[test]
    fn redemption_hash_is_stable_and_not_the_code() {
        let code = InviteCode::generate();
        assert_eq!(code.redemption_hash(), code.redemption_hash());
        assert!(!code.to_string().contains(&code.redemption_hash().to_hex()[..8]));
    }

    #[test]
    fn redemption_hash_hex_round_trips() {
        let hash = InviteCode::generate().redemption_hash();
        assert_eq!(RedemptionHash::from_hex(&hash.to_hex()).unwrap(), hash);
        assert!(RedemptionHash::from_hex("nonsense").is_none());
        assert!(RedemptionHash::from_hex(&"z".repeat(64)).is_none());
    }

    /// A code is a bearer credential; it must not appear in logs.
    #[test]
    fn debug_does_not_leak_the_code() {
        let code = InviteCode::generate();
        let rendered = format!("{code:?}");
        assert!(!rendered.contains(&code.to_string()));
        assert_eq!(rendered, "InviteCode(redacted)");
    }

    #[test]
    fn encoding_covers_the_full_range() {
        for secret in [[0u8; 8], [0xFF; 8], [0x01, 0x23, 0x45, 0x67, 0x89, 0xAB, 0xCD, 0xEF]] {
            let chars = encode_secret(&secret);
            let values: Vec<u8> = chars
                .iter()
                .map(|&c| normalise_char(c as char).unwrap())
                .collect();
            assert_eq!(decode_secret(&values), secret);
        }
    }
}
